   const ex = sg < 0 ? cx - gap / 2 : cx + gap / 2; ctx.fillStyle = '#2a3337'; ctx.fillRect(sg < 0 ? ex - gw * 0.55 : ex, cy - th / 2 + s * 0.42, gw * 0.55, gh + s * 0.04);
   // sello elastomérico con huecos (se comprime y ensancha)
