  const bx = w * 0.08, by = h * 0.06, BW = w * 0.84, BH = h * 0.66; ctx.fillStyle = 'rgba(12,30,52,0.92)'; ctx.beginPath(); ctx.roundRect(bx, by, BW, BH, 26); ctx.fill(); ctx.strokeStyle = 'rgba(69,199,232,0.85)'; ctx.lineWidth = 3; ctx.setLineDash([16, 8]); ctx.stroke(); ctx.setLineDash([]);
  ctx.strokeStyle = 'rgba(69,199,232,0.12)'; ctx.lineWidth = 1; for (let k = 1; k < 12; k++) { ctx.beginPath(); ctx.moveTo(bx + (k * BW) / 12, by); ctx.lineTo(bx + (k * BW) / 12, by + BH); ctx.stroke(); } for (let k = 1; k < 10; k++) { ctx.beginPath(); ctx.moveTo(bx, by + (k * BH) / 10); ctx.lineTo(bx + BW, by + (k * BH) / 10); ctx.stroke(); }
