  const RX = [bx + BW * 0.18, by + BH + h * 0.1], F = [bx + BW * 0.18, by + BH * 0.62], Cc = [bx + BW * 0.5, by + BH * 0.2], A = [bx + BW * 0.82, by + BH * 0.62], TX = [bx + BW * 0.82, by + BH + h * 0.1];
