  win(x + w * 0.07, y + rH + hF * 0.22, w * 0.22, hF * 0.5); win(x + w * 0.35, y + rH + hF * 0.22, w * 0.22, hF * 0.5); ctx.fillStyle = M('#2a1d14', '#4a3020'); ctx.fillRect(x + w * 0.7, y + rH + hF * 0.3, w * 0.16, hF * 0.7 - 16);
