  const e0 = [x - w * 0.05, y + rH + 6], e1 = [x + w + 8, y + rH + 6], r0 = [x + w * 0.04, y], r1 = [x + w + sd * 0.5, y - sd * 0.16]; const gr = ctx.createLinearGradient(0, y, 0, y + rH); gr.addColorStop(0, M('#2b1f1e', '#5a4440')); gr.addColorStop(1, M('#3a2a26', '#7a5a50')); ctx.fillStyle = gr; ctx.beginPath(); ctx.moveTo(e0[0], e0[1]); ctx.lineTo(e1[0], e1[1]); ctx.lineTo(r1[0], r1[1]); ctx.lineTo(r0[0], r0[1]); ctx.closePath(); ctx.fill();
  ctx.strokeStyle = M('#1a1212', '#3e2c28'); ctx.lineWidth = 1.6; for (let k = 1; k < 9; k++) { const f = k / 9; ctx.beginPath(); ctx.moveTo(lerp(e0[0], r0[0], f), lerp(e0[1], r0[1], f)); ctx.lineTo(lerp(e1[0], r1[0], f), lerp(e1[1], r1[1], f)); ctx.stroke(); } for (let k = 1; k < 22; k++) { const f = k / 22; ctx.beginPath(); ctx.moveTo(lerp(e0[0], e1[0], f), lerp(e0[1], e1[1], f)); ctx.lineTo(lerp(r0[0], r1[0], f), lerp(r0[1], r1[1], f)); ctx.stroke(); }
